const app=document.getElementById('app'),modal=document.getElementById('modal');
const S={meta:{demo:false,backend:'api'},profiles:[],user:null,csrf:'',spaces:[],data:null,history:[],jobs:[],agent:null,route:'home',wid:'',epoch:0,draft:'',filter:'',taskFilter:'all',pairPurpose:'ask',answerMode:'agent',mobile:false};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 12h16m-6-6 6 6-6 6',up:'m6 12 6-6 6 6m-6-6v15',plus:'M12 5v14M5 12h14',box:'m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v11',chat:'M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 13h8M8 17h5',tasks:'m3 6 2 2 3-4m3 2h10M3 14l2 2 3-4m3 2h10M3 21h18',shield:'m12 3-9 4v6c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-6',check:'m5 12 4 4L19 6',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3v.1',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm7 1a4 4 0 0 1 0 7m3 4a4 4 0 0 1 3 4v2',log:'M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1',logout:'M9 3H3v18h6m5-5 4-4-4-4m-7 4h15',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',link:'M9 15l6-6M9 6 7 6a5 5 0 0 0 0 10h2m6-10h2a5 5 0 0 1 0 10h-2',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3v.1',chevron:'m9 5 7 7-7 7',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',refresh:'M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 3M4 16l2 3a8 8 0 0 0 13-3',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const nameOf=id=>S.data?.members.find(m=>m.id===id)?.name||id;
const initials=n=>String(n||'R').split(' ').map(x=>x[0]).slice(0,2).join('');
const portrait=(p,cls='')=>`<span class="portrait ${['andi','maya','sari','dewi'].includes(p?.portrait)?'portrait-'+p.portrait:'portrait-fallback'} ${cls}" role="img" aria-label="${esc(p?.name||'Profil')}">${p?.portrait?'':esc(initials(p?.name))}</span>`;
const brand=()=>`<a class="brand" href="#home" aria-label="Relayfy beranda"><img src="/logo.svg" alt=""><strong>relayfy</strong><span>Handover Assistant</span></a>`;
const STATUS={'Draft':'Draf','Ready for Acceptance':'Siap diterima','Needs Clarification':'Perlu klarifikasi','Accepted':'Diterima'};
const badge=status=>`<span class="badge ${status==='Accepted'?'green':status==='Ready for Acceptance'?'blue':status==='Needs Clarification'?'amber':'neutral'}"><i></i>${esc(STATUS[status]||status)}</span>`;
const fmt=d=>new Date(d).toLocaleString('id-ID',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
let toastTimer;function toast(message,error=false){const el=document.getElementById('toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',6500);}
async function api(op,data,method=data?'POST':'GET'){
 const who=S.user?.id;let url='/api/'+op;if(method==='GET'&&data)url+='?'+new URLSearchParams(data);
 const r=await fetch(url,{method,credentials:'same-origin',cache:'no-store',headers:method==='POST'?{'Content-Type':'application/json','X-CSRF-Token':S.csrf}:{},body:method==='POST'?JSON.stringify(data):undefined});
 const out=await r.json();if(who&&who!==S.user?.id)throw Error('Sesi berubah. Permintaan lama diabaikan.');
 if(!r.ok){if(r.status===401&&S.user){clearUser();location.hash='login';}throw Error(out.error||'Permintaan gagal.');}return out;
}
function clearUser(){S.user=null;S.csrf='';S.data=null;S.history=[];S.jobs=[];S.spaces=[];S.agent=null;S.draft='';S.answerMode='agent';S.mobile=false;S.epoch++;modal.close();}
function showDialog(content,wide=false){modal.className=wide?'wide':'';modal.innerHTML=`<button class="icon-btn dialog-close" aria-label="Tutup dialog">${icon('close')}</button>${content}`;if(!modal.open)modal.showModal();modal.querySelector('.dialog-close').onclick=()=>modal.close();}
function bindTheme(){document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=()=>{const theme=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('relayfy-theme',theme);}catch{}});}
try{document.documentElement.dataset.theme=localStorage.getItem('relayfy-theme')||'dark';}catch{document.documentElement.dataset.theme='dark';}
function publicNav(){return `<header class="public-nav"><div>${brand()}<nav aria-label="Navigasi produk"><a href="#home">Produk</a><a href="#profiles">Workspace</a><a href="#guide">Panduan</a></nav><div class="public-actions"><span class="lang-tag">ID</span><button class="icon-btn" data-theme-toggle aria-label="Ganti tema">${icon('sun')}</button><a class="button white small" href="#${S.user?'dashboard':S.meta.demo?'profiles':'login'}">Buka workspace ${icon('arrow')}</a></div></div></header>`;}
function homeExample(tab='brief'){
 if(tab==='tasks')return `<div class="lp-paper-heading"><span class="lp-paper-label">03 PEKERJAAN TERBUKA</span><span class="lp-paper-status">Dari daftar tugas</span></div><h3>Pekerjaan berikutnya,<br><em>terlihat jelas.</em></h3><p class="lp-paper-intro">Yang belum selesai tetap punya tempat. Informasi yang kosong tetap ditandai.</p><div class="lp-example-tasks"><div><span class="lp-task-dot"></span><div><strong>Integrasi pembayaran</strong><small>Menunggu akun sandbox</small></div><span class="lp-missing-tag">PIC belum ada</span></div><div><span class="lp-task-dot"></span><div><strong>Unggah foto produk</strong><small>Maya Anggraini · 6 Nov</small></div><span class="lp-task-label">Terbuka</span></div><div><span class="lp-task-dot"></span><div><strong>Review aksesibilitas katalog</strong><small>Andi Pratama · 5 Nov</small></div><span class="lp-task-label">Dikerjakan</span></div></div><div class="lp-paper-foot">${icon('file')} Contoh dari Papan pekerjaan engineering.</div>`;
 if(tab==='sources')return `<div class="lp-paper-heading"><span class="lp-paper-label">BAHAN HANDOVER</span><span class="lp-paper-status">Contoh sumber</span></div><h3>Konteksnya ada.<br><em>Asalnya juga.</em></h3><p class="lp-paper-intro">Dokumen, percakapan, dan tugas dibaca sesuai izin pengguna.</p><div class="lp-example-sources"><div>${icon('file')}<span><strong>Brief proyek Karsa</strong><small>Tujuan, keputusan, dan ruang lingkup</small></span><span>01</span></div><div>${icon('chat')}<span><strong>Chat tim</strong><small>Pembaruan jadwal dan hambatan</small></span><span>02</span></div><div>${icon('tasks')}<span><strong>Papan pekerjaan</strong><small>Status, PIC, dan ketergantungan</small></span><span>03</span></div></div><div class="lp-paper-foot">${icon('shield')} Sumber diperiksa izinnya sebelum pencarian.</div>`;
 return `<div class="lp-paper-heading"><span class="lp-paper-label">HANDOVER BRIEF / 001</span><span class="lp-paper-status"><i></i> Draf untuk ditinjau</span></div><h3>Yang perlu<br><em>Maya lanjutkan.</em></h3><p class="lp-paper-intro">Peluncuran Karsa Commerce</p><div class="lp-brief-excerpt"><span class="lp-paper-label">KEPUTUSAN TERAKHIR</span><p>Gunakan katalog statis untuk demo, sebelum integrasi transaksi produksi.</p><button class="lp-citation" id="lp-open-citation">${icon('file')} Brief proyek Karsa <span>↗</span></button></div><div class="lp-paper-alert"><span>!</span><div><strong>Jadwal perlu dikonfirmasi</strong><p>Brief mencatat 7 Nov. Chat mencatat 9 Nov.<br>Tanggal final belum ditentukan.</p></div></div><div class="lp-paper-foot">${icon('eye')} Ditinjau pemberi sebelum dibagikan kepada penerima.</div>`;
}
function renderHome(){
 const entry='#'+(S.user?'dashboard':S.meta.demo?'profiles':'login');
 app.innerHTML=`<div class="lp-page"><header class="lp-nav"><div class="lp-container lp-nav-inner">${brand()}<nav aria-label="Navigasi beranda"><button data-home-scroll="lp-inside">Di dalam Relayfy</button><button data-home-scroll="lp-flow">Alur kerja</button><a href="#guide">Panduan</a></nav><div class="lp-nav-actions"><button class="icon-btn" data-theme-toggle aria-label="Ganti tema">${icon('sun')}</button><a href="${entry}" class="lp-nav-enter">Buka workspace ${icon('arrow')}</a></div></div></header><main>
 <section class="lp-hero lp-container"><div class="lp-overline"><span></span> RUANG UNTUK MENERUSKAN PEKERJAAN</div><h1>Pekerjaan berpindah.<br><em>Konteks tetap utuh.</em></h1><p class="lp-hero-description">Satukan keputusan, cerita di balik pekerjaan,<br class="lp-desktop-break"> dan langkah berikutnya untuk orang yang melanjutkan.</p><div class="lp-hero-actions"><a class="lp-primary" href="${entry}">Mulai handover ${icon('arrow')}</a><button class="lp-secondary" data-home-scroll="lp-preview">Jelajahi contohnya <span>↓</span></button></div><div class="lp-hero-note"><span class="lp-note-line"></span>Untuk orang yang menyerahkan. Untuk orang yang melanjutkan.<span class="lp-note-line"></span></div></section>
 <section class="lp-container lp-preview-section" id="lp-preview" aria-label="Pratinjau handover dengan data contoh"><div class="lp-preview-caption"><span><i></i> SEKILAS DI DALAM RELAYFY</span><span>Pratinjau interaktif · data sintetis</span></div><div class="lp-window"><div class="lp-window-top"><div><img src="/logo.svg" alt=""><span>Workspace</span><span class="lp-breadcrumb">/</span><strong>Karsa Commerce</strong></div><span class="lp-window-mode">HANDOVER PROYEK</span></div><div class="lp-window-body"><aside class="lp-preview-sidebar"><div class="lp-preview-project"><span class="lp-project-monogram">K.</span><div><strong>Satu proyek.<br>Banyak konteks.</strong><p>Dirapikan dalam satu handover.</p></div></div><div class="lp-preview-tabs" role="tablist" aria-label="Jelajahi contoh handover" aria-orientation="vertical"><button id="lp-tab-brief" role="tab" data-example="brief" aria-selected="true" aria-controls="lp-example-panel"><span>01</span> Brief handover ${icon('arrow')}</button><button id="lp-tab-tasks" role="tab" data-example="tasks" aria-selected="false" aria-controls="lp-example-panel" tabindex="-1"><span>02</span> Pekerjaan terbuka ${icon('arrow')}</button><button id="lp-tab-sources" role="tab" data-example="sources" aria-selected="false" aria-controls="lp-example-panel" tabindex="-1"><span>03</span> Sumber & konteks ${icon('arrow')}</button></div><div class="lp-handover-people"><span class="lp-paper-label">BERPINDAH TANGAN, TETAP TERSAMBUNG</span><div><span class="portrait portrait-andi lp-person" role="img" aria-label="Andi, profil sintetis"></span><span>Andi</span>${icon('arrow')}<span class="portrait portrait-maya lp-person" role="img" aria-label="Maya, profil sintetis"></span><span>Maya</span></div></div></aside><div class="lp-paper-desk"><div class="lp-paper" id="lp-example-panel" role="tabpanel" aria-labelledby="lp-tab-brief" tabindex="0">${homeExample()}</div><span class="lp-desk-label">CONTEXT, CARRIED FORWARD.</span></div></div></div><div class="lp-preview-footer"><span>Pratinjau memakai data contoh. Coba alur lengkapnya di workspace.</span><a href="${entry}">Buka workspace demo ${icon('arrow')}</a></div></section>
 <section class="lp-container lp-inside" id="lp-inside"><div class="lp-section-intro"><span class="lp-overline">DIBUAT UNTUK MOMEN PERALIHAN</span><h2>Orang baru.<br><em>Tak harus mulai<br>dari nol.</em></h2><p>Informasi penting tetap bisa ditemukan ketika tanggung jawab berganti tangan.</p></div><div class="lp-editorial-list"><article><span class="lp-item-index">01 /</span><div><h3>Jawaban yang bisa ditelusuri.</h3><p>Tanyakan alasan keputusan atau status pekerjaan. Buka kutipannya untuk melihat dari mana jawabannya berasal.</p><span class="lp-editorial-note">Setiap kesimpulan perlu bukti.</span></div>${icon('link')}</article><article><span class="lp-item-index">02 /</span><div><h3>Yang belum jelas, tetap terlihat.</h3><p>PIC kosong, tenggat yang belum ada, dan sumber yang berbeda ditandai untuk diklarifikasi bersama.</p><span class="lp-editorial-note">Tidak ada kepastian yang dikarang.</span></div>${icon('alert')}</article><article><span class="lp-item-index">03 /</span><div><h3>Selesai dengan tinjauanmu.</h3><p>Pemberi memeriksa dan membagikan versi. Penerima membaca, bertanya, lalu menerima konteks yang disepakati.</p><span class="lp-editorial-note">Keputusan terakhir tetap pada manusia.</span></div>${icon('check')}</article></div></section>
 <section class="lp-flow-section" id="lp-flow"><div class="lp-container"><div class="lp-flow-heading"><div><span class="lp-overline">ALUR YANG BISA DIIKUTI</span><h2>Dari bahan yang tersebar,<br>ke handover yang jelas.</h2></div><a href="#guide" class="lp-inline-link">Baca panduan ${icon('arrow')}</a></div><ol class="lp-flow"><li><span>01</span><h3>Kumpulkan</h3><p>Masukkan dokumen, ekspor chat, dan daftar tugas. Tentukan siapa yang boleh membaca.</p></li><li><span>02</span><h3>Pahami</h3><p>Susun brief bersama agent. Telusuri sumber, keputusan, dan pekerjaan yang masih terbuka.</p></li><li><span>03</span><h3>Tinjau</h3><p>Periksa temuan. Klarifikasi yang kurang, lalu bagikan versi yang sudah ditinjau.</p></li><li><span>04</span><h3>Lanjutkan</h3><p>Penerima menyetujui versi handover. Konteks dan jejak keputusan tetap tercatat.</p></li></ol></div></section>
 <section class="lp-container lp-faq-section"><div class="lp-section-intro"><span class="lp-overline">SEBELUM MULAI</span><h2>Beberapa hal<br><em>yang perlu kamu tahu.</em></h2></div><div class="lp-faq"><details><summary>Apakah ini memakai data perusahaan sungguhan?<span>+</span></summary><p>Demo ini menggunakan profil, foto, dokumen, chat, dan tugas sintetis. Kamu bisa menjelajahi alurnya dengan bahan contoh yang sudah tersedia.</p></details><details><summary>Bagaimana agent AI-nya bekerja?<span>+</span></summary><p>Web menyiapkan permintaan dan bukti sesuai izin. Setelah dihubungkan, tool WorkBuddy mengambil pekerjaan, menyusun hasil, lalu mengembalikannya ke web untuk divalidasi. Pada versi lokal ini agent perlu dijalankan dari WorkBuddy; koneksi belum bekerja otomatis hanya dengan membuka website.</p></details><details><summary>Apakah brief langsung dibagikan ke penerima?<span>+</span></summary><p>Belum. Brief tetap menjadi draf privat sampai pemberi meninjau dan mengonfirmasi pembagiannya. Penerima kemudian dapat meminta klarifikasi atau menerima versi tersebut.</p></details><details><summary>Bagaimana kalau buktinya belum cukup?<span>+</span></summary><p>Relayfy menampilkan informasi yang belum tersedia dan konflik sumber yang ditemukan. PIC, deadline, atau tanggal final tidak ditebak. Pemeriksaan otomatis tetap perlu ditinjau manusia.</p></details></div></section>
 <section class="lp-container lp-final"><span class="lp-overline">KEEP WORK MOVING.</span><h2>Berikan awal yang lebih baik<br><em>untuk orang berikutnya.</em></h2><a class="lp-primary" href="${entry}">Buka workspace ${icon('arrow')}</a><p>Demo lokal · sumber sintetis · persetujuan per versi</p></section></main><footer class="lp-footer"><div class="lp-container"><div>${brand()}<p>Context, carried forward.</p></div><div><span>Prototipe untuk Tencent Cloud Hackathon Indonesia 2026</span><small>Challenge A — The Workplace Brain</small></div><a href="#guide">Panduan penggunaan ${icon('arrow')}</a></div></footer></div>`;
 bindTheme();
 document.querySelectorAll('[data-home-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.homeScroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}));
 const tabs=[...document.querySelectorAll('[data-example]')];
 document.querySelector('.lp-preview-tabs').setAttribute('aria-orientation',matchMedia('(max-width: 600px)').matches?'horizontal':'vertical');
 const selectTab=b=>{tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1;});const panel=document.getElementById('lp-example-panel');panel.setAttribute('aria-labelledby',b.id);panel.innerHTML=homeExample(b.dataset.example);bindExampleCitation();};
 const bindExampleCitation=()=>{const b=document.getElementById('lp-open-citation');if(b)b.onclick=()=>showDialog(`<span class="eyebrow">CONTOH SUMBER · DATA SINTETIS</span><h2>Brief proyek Karsa</h2><p class="muted small-text">karsa-brief:3 · Versi 1 · Berlaku 29 Oktober 2026</p><blockquote>Keputusan: Gunakan katalog statis untuk demo, sebelum integrasi transaksi produksi.</blockquote><p class="small-text muted">Kutipan contoh untuk menjelaskan produk. Sumber dalam workspace yang sebenarnya diperiksa kembali sesuai izin akunmu.</p>`);};
 tabs.forEach((b,i)=>{b.onclick=()=>selectTab(b);b.onkeydown=e=>{let j;if(['ArrowDown','ArrowRight'].includes(e.key))j=(i+1)%tabs.length;else if(['ArrowUp','ArrowLeft'].includes(e.key))j=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')j=0;else if(e.key==='End')j=tabs.length-1;else return;e.preventDefault();selectTab(tabs[j]);tabs[j].focus();};});
 bindExampleCitation();
}
async function renderProfiles(){
 if(!S.meta.demo){renderAuth(false);return;}
 if(!S.profiles.length)S.profiles=await api('profiles');
 app.innerHTML=`<div class="profile-screen"><header class="profile-header">${brand()}<div><span class="lang-tag">ID</span><button class="icon-btn" data-theme-toggle aria-label="Ganti tema">${icon('sun')}</button></div></header><main class="profiles-main"><div class="profiles-heading"><span class="eyebrow">TEMUKAN SUDUT PANDANGMU</span><h1>Pilih profil demo</h1><p>Masuk sebagai siapa? Setiap profil punya konteks dan akses yang berbeda.</p></div><div class="profiles-grid">${S.profiles.map(p=>`<button class="profile-card" data-profile="${esc(p.slug)}">${portrait(p,'profile-photo')}<span class="profile-info"><strong>${esc(p.name)}</strong><span>${esc(p.title)}</span><small>${esc(p.department)}</small><em class="role-tag role-${p.slug}">${esc(p.badge)}</em><span class="profile-description">${esc(p.description)}</span><span class="profile-enter">Masuk workspace ${icon('arrow')}</span></span></button>`).join('')}</div><div class="profiles-footer"><p>${icon('shield')} Pilihan profil ini adalah simulasi identitas untuk demo lokal. Seluruh bahan dan foto bersifat sintetis.</p><span>Izin tetap diperiksa oleh server, bukan dari klaim peran di chat.</span><a href="#login">Gunakan akun sendiri ${icon('arrow')}</a></div></main></div>`;
 bindTheme();document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{if(S.user){await api('logout',{});clearUser();}const r=await api('demo-login',{profile:b.dataset.profile});S.user=r.user;S.csrf=r.csrf;S.draft='';location.hash='dashboard';if(S.route==='dashboard')await loadRoute();}catch(e){toast(e.message,true);b.disabled=false;}});
}
function renderAuth(register=false){app.innerHTML=`${publicNav()}<main class="auth-page"><section><span class="eyebrow">KONTEKS YANG TEPAT, UNTUK ORANG YANG TEPAT.</span><h1>${register?'Mulai handover pertamamu.':'Selamat datang kembali.'}</h1><p class="muted">${register?'Buat akun untuk berbagi pekerjaan dengan lebih jelas.':'Masuk untuk melanjutkan konteks pekerjaanmu.'}</p><form id="auth-form">${register?'<label>Nama lengkap<input name="name" required maxlength="100" autocomplete="name" placeholder="Nama kamu"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email" placeholder="nama@perusahaan.com"></label><label>Password<input name="password" type="password" required minlength="12" maxlength="200" autocomplete="${register?'new-password':'current-password'}" placeholder="Minimal 12 karakter"></label><p class="form-error" id="auth-error" role="alert"></p><button class="button white full">${register?'Buat akun':'Masuk'} ${icon('arrow')}</button></form><p class="auth-switch">${register?'Sudah memiliki akun?':'Belum punya akun?'} <a href="#${register?'login':'register'}">${register?'Masuk':'Daftar'}</a></p>${S.meta.demo?'<a class="text-link" href="#profiles">Coba profil demo '+icon('arrow')+'</a>':''}</section><aside><div class="auth-art"><span class="auth-letter">r</span><div class="auth-arrow">${icon('arrow')}</div></div><h2>Pekerjaan berganti tangan.<br><em>Konteks tetap utuh.</em></h2></aside></main>`;bindTheme();document.getElementById('auth-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;b.textContent='Memproses…';try{const r=await api(register?'register':'login',Object.fromEntries(new FormData(e.target)));S.user=r.user;S.csrf=r.csrf;location.hash='dashboard';if(S.route==='dashboard')await loadRoute();}catch(err){document.getElementById('auth-error').textContent=err.message;b.disabled=false;b.textContent=register?'Buat akun':'Masuk';}};}
const routeLabel={dashboard:'Ringkasan',ask:'Chat',workspace:'Workspace',sources:'Perpustakaan sumber',tasks:'Pekerjaan terbuka',gaps:'Informasi kurang',review:'Review & penerimaan',activity:'Activity log',connection:'WorkBuddy',guide:'Panduan'};
function shell(content){
 const w=S.data?.workspace,selected=S.spaces.find(x=>x.id===S.wid)||S.spaces[0];
 const role=w?(w.giver===S.user.id?'Pemberi handover':w.receiver===S.user.id?'Penerima handover':'Anggota workspace'):(S.user.badge||'Akun pengguna');
 const nav=(r,label,ic)=>`<a class="side-link ${S.route===r?'active':''}" href="#${r}${['dashboard','guide'].includes(r)?'':selected?'/'+selected.id:''}">${icon(ic)}${label}${r==='gaps'&&S.data?`<span>${S.data.analysis.missing.length+S.data.analysis.conflicts.length}</span>`:''}</a>`;
 app.innerHTML=`<div class="app-layout ${S.mobile?'nav-open':''}"><button class="nav-scrim" id="nav-scrim" aria-label="Tutup navigasi"></button><aside class="sidebar"><div class="sidebar-brand">${brand()}<button class="icon-btn mobile-only" id="close-nav" aria-label="Tutup navigasi">${icon('close')}</button></div><div class="sidebar-content"><nav aria-label="Navigasi workspace">${nav('dashboard','Ringkasan','grid')}${nav('ask','Chat','chat')}<span class="nav-caption">Handover</span>${nav('workspace','Workspace','box')}${nav('tasks','Pekerjaan terbuka','tasks')}${nav('gaps','Informasi kurang','alert')}${nav('review','Review & penerimaan','check')}<span class="nav-caption">Referensi</span>${nav('sources','Perpustakaan sumber','file')}${nav('activity','Activity log','log')}<span class="nav-caption">Agent</span>${nav('connection','Hubungkan WorkBuddy','link')}</nav></div><div class="sidebar-bottom">${nav('guide','Panduan','help')}<div class="sidebar-footnote"><i class="orange-dot"></i> KEEP WORK MOVING <button class="icon-btn" data-theme-toggle aria-label="Ganti tema">${icon('sun')}</button></div><div class="user-profile">${portrait(S.user,'avatar')}<div><strong>${esc(S.user.name)}</strong><small>${esc(role)}</small></div><button class="icon-btn" id="logout" aria-label="${S.meta.demo?'Ganti profil':'Keluar'}" title="${S.meta.demo?'Ganti profil':'Keluar'}">${icon('logout')}</button></div></div></aside><div class="app-main"><header class="app-topbar"><div class="topbar-left"><button class="icon-btn mobile-only" id="open-nav" aria-label="Buka navigasi">${icon('menu')}</button><strong>${esc(routeLabel[S.route]||'Relayfy')}</strong>${selected?`<span class="top-divider"></span><select id="workspace-picker" aria-label="Pilih workspace">${S.spaces.map(x=>`<option value="${x.id}" ${x.id===selected.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}</div><div class="topbar-right"><button class="agent-indicator ${S.agent?.active?'online':''}" id="agent-connect"><i></i><span>${S.meta.backend==='workbuddy'?S.agent?.active?'Tool agent aktif':'WorkBuddy belum aktif':S.meta.model_ready?'API dikonfigurasi':'AI belum dikonfigurasi'}</span></button><button class="icon-btn" data-theme-toggle aria-label="Ganti tema">${icon('sun')}</button></div></header><main id="main" class="content ${S.route==='ask'?'chat-content':''}">${content}</main><footer class="app-footer">Relayfy bisa keliru. Periksa sumber dan tinjau sebelum menerima handover.<span>${S.meta.demo?'Demo sintetis · lokal':'Akses mengikuti akunmu'}</span></footer></div></div>`;
 bindTheme();document.getElementById('logout').onclick=async()=>{try{await api('logout',{});clearUser();location.hash=S.meta.demo?'profiles':'login';}catch(e){toast(e.message,true);}};
 const open=document.getElementById('open-nav'),close=document.getElementById('close-nav');if(open)open.onclick=()=>{S.mobile=true;document.querySelector('.app-layout').classList.add('nav-open');};if(close)close.onclick=closeNav;document.getElementById('nav-scrim').onclick=closeNav;
 const picker=document.getElementById('workspace-picker');if(picker)picker.onchange=e=>{S.draft='';location.hash=(S.route==='dashboard'?'workspace':S.route)+'/'+e.target.value;};
 document.getElementById('agent-connect').onclick=()=>S.data?pairDialog():toast('Buka workspace terlebih dahulu.');bindContent();
}
function closeNav(){S.mobile=false;document.querySelector('.app-layout')?.classList.remove('nav-open');}
const heading=(eyebrow,title,desc,action='')=>`<section class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="muted">${desc}</p></div>${action}</section>`;
function empty(ic,title,desc,action=''){return `<div class="empty-state">${icon(ic)}<h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function workspaceHref(route='workspace'){return '#'+route+'/'+S.wid;}
function renderDashboard(){
 const spaces=S.spaces,accepted=spaces.filter(x=>x.status==='Accepted').length,open=spaces.reduce((n,x)=>n+x.open_tasks,0),gaps=spaces.reduce((n,x)=>n+x.gaps,0);
 shell(heading('YOUR NEXT CHAPTER',`Selamat ${new Date().getHours()<11?'pagi':new Date().getHours()<15?'siang':new Date().getHours()<18?'sore':'datang'}, ${esc(S.user.name.split(' ')[0])}.`,'Semua yang perlu diteruskan, tersambung di sini.',`<button class="button white" id="new-workspace">${icon('plus')} Handover baru</button>`)+`<section class="dashboard-banner"><div><span class="mini-label">KONTEKS TETAP ADA, MESKI ORANGNYA BERGANTI.</span><h2>Mulai dengan konteks.<br>Lanjutkan dengan jelas.</h2><p>Pahami keputusan, temukan pekerjaan terbuka,<br>dan serahkan versi yang sudah ditinjau.</p><a class="text-link" href="#guide">Pelajari alurnya ${icon('arrow')}</a></div><div class="banner-visual"><span class="outline-box">${icon('file')}</span><span class="banner-link">${icon('arrow')}</span><span class="solid-box">${icon('check')}</span></div></section><div class="stats-row"><div><span>${icon('box')} Handover aktif</span><strong>${spaces.length.toString().padStart(2,'0')}</strong><small>Workspace yang dapat kamu buka</small></div><div><span>${icon('tasks')} Pekerjaan terbuka</span><strong>${open.toString().padStart(2,'0')}</strong><small>Dari sumber yang diizinkan</small></div><div><span>${icon('alert')} Perlu diperjelas</span><strong>${gaps.toString().padStart(2,'0')}</strong><small>Gap dan konflik sumber</small></div><div><span>${icon('check')} Sudah diterima</span><strong>${accepted.toString().padStart(2,'0')}</strong><small>Versi handover yang diterima</small></div></div><section><div class="section-heading"><h2>Workspace handover <span class="counter">${spaces.length}</span></h2><span class="muted small-text">Tempat konteks berpindah tangan.</span></div>${spaces.length?`<div class="space-list">${spaces.map(w=>`<a class="space-card" href="#workspace/${w.id}"><div class="space-card-top"><span class="space-symbol">${icon('box')}</span>${badge(w.status)}</div><div class="eyebrow">${w.giver===S.user.id?'KAMU PEMBERI':w.receiver===S.user.id?'KAMU PENERIMA':'ANGGOTA WORKSPACE'}</div><h3>${esc(w.name)}</h3><p>${esc(w.giver_name)} ${icon('arrow')} ${esc(w.receiver_name)}</p><div class="space-counts"><span>${icon('file')} ${w.source_count} sumber</span><span>${icon('tasks')} ${w.open_tasks} terbuka</span><span>Revisi ${w.revision}</span></div><div class="space-card-bottom">Lanjutkan handover ${icon('arrow')}</div></a>`).join('')}<button class="space-card new-space" id="new-workspace-card">${icon('plus')}<strong>Ruang untuk pekerjaan berikutnya</strong><span>Buat handover baru</span></button></div>`:empty('box','Belum ada handover','Mulai dengan membuat workspace dan memilih penerima.','<button class="button white" id="empty-create">Buat handover '+icon('arrow')+'</button>')}</section><div class="dashboard-bottom"><span>${icon('shield')} ${S.meta.demo?'Kamu menggunakan profil demo dengan data sintetis.':'Izin akunmu diperiksa pada setiap permintaan.'}</span><a class="text-link" href="#${S.meta.demo?'profiles':'guide'}">${S.meta.demo?'Jelajahi profil lain':'Panduan'} ${icon('arrow')}</a></div>`);
 ['new-workspace','new-workspace-card','empty-create'].forEach(id=>{const b=document.getElementById(id);if(b)b.onclick=createDialog;});
}
function tabs(active){return `<div class="workspace-tabs">${[['workspace','Ringkasan'],['sources','Sumber'],['tasks','Pekerjaan'],['gaps','Kelengkapan'],['review','Review']].map(([r,n])=>`<a href="#${r}/${S.wid}" class="${active===r?'active':''}">${n}</a>`).join('')}</div>`;}
function workspaceHeading(){const w=S.data.workspace;return heading('HANDOVER WORKSPACE',esc(w.name),'Konteks yang sama, dengan akses sesuai tanggung jawabmu.',`<div class="heading-actions">${badge(w.status)}<a class="button secondary" href="${workspaceHref('ask')}">${icon('chat')} Tanya Relayfy</a></div>`)+`<div class="workspace-meta"><span>Revisi ${w.revision}</span><i></i><span>${esc(nameOf(w.giver))} ${icon('arrow')} ${esc(nameOf(w.receiver))}</span></div>`+tabs(S.route);}
function cite(e,label){return `<button class="citation" data-cite="${esc(e.citation)}">${icon('file')} ${esc(label||e.title||e.citation)} ${icon('link')}</button>`;}
function conflicts(items){return (items||[]).map(c=>`<div class="conflict-card"><div class="conflict-title">${icon('alert')} ${esc(c.field)}: sumber belum selaras</div><div class="conflict-options">${c.sources.map(e=>`<div><strong>${esc(e.value)}</strong>${cite(e)}</div>`).join('')}</div><p>${esc(c.decision)}</p></div>`).join('');}
function answer(a){return `${a.unknown?`<p>${esc(a.message||'Informasi belum tersedia untuk pertanyaan ini.')}</p>`:''}${a.origin==='retrieval'&&a.evidence?.length?`<p class="answer-notice">Kutipan langsung dari sumber. Belum disintesis model AI.</p>${a.evidence.map(e=>`<div class="quote-item"><p>${esc(e.text)}</p>${cite(e)}</div>`).join('')}`:''}${(a.claims||[]).map(c=>`<div class="answer-claim"><p>${esc(c.text)}</p>${cite({citation:c.citation})}<details class="quote-details"><summary>Periksa kutipan</summary><blockquote>${esc(c.quote)}</blockquote></details></div>`).join('')}${a.clarification?`<div class="clarification-note">${icon('chat')}<span>${esc(a.clarification)}</span></div>`:''}${conflicts(a.conflicts)}`;}
function clarificationsPanel(){return (S.data.clarifications||[]).length?`<section class="clarifications-panel"><h3>${icon('chat')} Pertanyaan penerima</h3>${S.data.clarifications.map(c=>`<p>${esc(c.question)}</p><small>${esc(fmt(c.created))}</small>`).join('')}</section>`:'';}
function pendingBrief(){const j=S.jobs.find(x=>x.mode==='brief'&&['Pending','Processing'].includes(x.status));return j?`<div class="agent-wait"><span class="spinner"></span><div><strong>${j.status==='Processing'?'Tool agent sedang memproses brief':'Brief menunggu WorkBuddy'}</strong><p>Bukti sudah difilter untuk penerima. Buka task WorkBuddy baru dengan koneksi tujuan brief.</p><button class="text-btn" id="connect-brief">Hubungkan agent penyusun brief ${icon('arrow')}</button></div><button class="icon-btn" data-cancel-job="${j.id}" aria-label="Batalkan antrean">${icon('close')}</button></div>`:'';}
function renderWorkspace(){const d=S.data,w=d.workspace,a=d.analysis,b=d.briefs[0],giver=w.giver===S.user.id;
 shell(workspaceHeading()+pendingBrief()+clarificationsPanel()+`<div class="workspace-grid"><section class="panel brief-panel"><div class="section-heading"><h2>${icon('spark')} Handover brief</h2>${b?badge(b.status):'<span class="muted small-text">Belum tersedia</span>'}</div>${b?`<div class="brief-info"><span>Versi ${esc(b.id.slice(0,8))}</span><span>Revisi ${b.revision}</span><span>${b.kind==='extractive'?'Kutipan tanpa AI':b.kind==='workbuddy'?'Melalui tool agent':'Model API'}</span></div>${b.ai?answer(b.ai):b.evidence.map(e=>`<div class="quote-item"><p>${esc(e.text)}</p>${cite(e)}</div>`).join('')}${conflicts(b.conflicts)}<div class="brief-action-row">${reviewButtons(b,giver)}</div>`:empty('file',giver?'Susun konteks untuk penerima':'Menunggu handover dari pemberi',giver?'Draf disusun dari sumber yang diizinkan untuk penerima, lalu kamu tinjau sebelum dibagikan.':'Pemberi perlu meninjau dan membagikan versi sebelum kamu dapat membacanya.',giver?'<button class="button white" id="generate-brief">'+icon('spark')+' Susun brief dengan agent</button>':'')}</section><aside class="context-sidebar"><section class="panel"><span class="eyebrow">ORANG DI BALIK PEKERJAAN</span>${d.members.filter(m=>[w.giver,w.receiver].includes(m.id)).map(m=>`<div class="person-row">${portrait(m,'avatar')}<div><strong>${esc(m.name)}</strong><small>${m.id===w.giver?'Pemberi handover':'Penerima handover'}</small></div></div>`).join('')}<div class="context-lines"><div><span>Sumber berizin</span><strong>${d.sources.length}</strong></div><div><span>Pekerjaan terbuka</span><strong>${a.tasks.filter(t=>!['done','selesai'].includes(t.status.toLowerCase())).length}</strong></div><div><span>Informasi kurang</span><strong>${a.missing.length}</strong></div></div></section><div class="context-note">${icon('shield')}<p>Perubahan bahan atau izin membuka revisi baru. Hasil lama perlu ditinjau ulang.</p></div>${giver?`<button class="button secondary full" id="generate-secondary">${icon('spark')} Susun brief dengan agent</button><button class="button subtle full" id="extractive">Lihat ringkasan bukti</button><p class="tiny muted">Ringkasan bukti bersifat ekstraktif dan dapat digunakan tanpa model AI.</p>`:''}</aside></div>`);
 bindWorkspaceActions(b,giver);const cb=document.getElementById('connect-brief');if(cb)cb.onclick=()=>pairDialog('brief');
}
function reviewButtons(b,giver){if(giver&&['Draft','Needs Clarification'].includes(b.status))return `<button class="button white" id="review-share">${icon('check')} Tinjau & bagikan versi</button>`;if(!giver&&S.user.id===S.data.workspace.receiver&&b.status==='Ready for Acceptance')return `<button class="button white" id="accept-handover">${icon('check')} Terima handover</button><button class="button secondary" id="clarify-handover">Minta klarifikasi</button>`;if(b.status==='Accepted')return `<span class="accepted-note">${icon('check')} Versi ini telah diterima. Tugas terbuka tetap perlu dilanjutkan.</span>`;return '<span class="small-text muted">Persetujuan mengikuti peran dan status versi handover.</span>';}
function bindWorkspaceActions(b,giver){
 ['generate-brief','generate-secondary','generate-review'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=()=>generate('generate',el);});
 const ex=document.getElementById('extractive');if(ex)ex.onclick=()=>generate('extractive',ex);
 const review=document.getElementById('review-share');if(review)review.onclick=()=>approval('review',{brief:b.id},'Tinjau & bagikan versi','Penerima akan dapat melihat versi ini. Periksa kutipan, konflik, dan informasi yang masih kurang.');
 const accept=document.getElementById('accept-handover');if(accept)accept.onclick=()=>approval('accept',{brief:b.id},'Terima handover ini?','Kamu menerima versi ini, termasuk pekerjaan terbuka dan informasi kurang yang masih tercatat. Ini tidak menandakan semua tugas selesai.');
 const clarify=document.getElementById('clarify-handover');if(clarify)clarify.onclick=()=>{showDialog(`<span class="eyebrow">KLARIFIKASI</span><h2>Apa yang perlu diperjelas?</h2><p class="muted">Pertanyaan ditampilkan kepada pemberi dan dicatat pada revisi ini.</p><form id="clarify-form"><label>Pertanyaan<textarea name="question" required maxlength="2000" rows="4" placeholder="Contoh: siapa PIC pengganti pembayaran?"></textarea></label><button class="button white full">Tinjau permintaan ${icon('arrow')}</button></form>`);document.getElementById('clarify-form').onsubmit=e=>{e.preventDefault();approval('clarify',{brief:b.id,question:new FormData(e.target).get('question')},'Bagikan pertanyaan klarifikasi','Pertanyaan ini akan diterima pemberi dan status handover berubah menjadi perlu klarifikasi.');};};
}
function renderSources(){const d=S.data,giver=d.workspace.giver===S.user.id;
 shell(workspaceHeading()+`<section class="panel"><div class="section-heading"><div><h2>Perpustakaan sumber <span class="counter">${d.sources.length}</span></h2><p class="muted small-text">Hanya bahan yang diizinkan untuk akunmu.</p></div>${giver?'<button class="button white" id="add-source">'+icon('plus')+' Tambah sumber</button>':''}</div><label class="search-field">${icon('search')}<input id="source-search" placeholder="Cari judul sumber…" value="${esc(S.filter)}" aria-label="Cari sumber"></label><div id="sources-list">${sourceRows(d.sources.filter(s=>s.title.toLowerCase().includes(S.filter.toLowerCase())),giver)}</div></section>`);
 const input=document.getElementById('source-search');input.oninput=e=>{S.filter=e.target.value;document.getElementById('sources-list').innerHTML=sourceRows(d.sources.filter(s=>s.title.toLowerCase().includes(S.filter.toLowerCase())),giver);bindContent();};const add=document.getElementById('add-source');if(add)add.onclick=sourceDialog;
}
function sourceRows(rows,giver){return rows.length?rows.map(s=>`<article class="source-row"><span class="source-icon kind-${s.kind}">${icon(s.kind==='chat'?'chat':s.kind==='tasks'?'tasks':'file')}</span><div class="source-name"><strong>${esc(s.title)}</strong><small>${esc({document:'Dokumen',chat:'Percakapan',tasks:'Daftar tugas'}[s.kind]||s.kind)} · Versi ${s.version}${s.effective?' · '+esc(s.effective):''}</small></div>${giver?`<span class="source-audience">${icon('users')} ${s.users.length} anggota</span>`:''}<button class="button subtle" data-source="${s.id}">Buka ${icon('arrow')}</button>${giver?`<button class="icon-btn" data-acl="${s.id}" aria-label="Atur akses ${esc(s.title)}" title="Atur akses">${icon('shield')}</button>`:''}</article>`).join(''):empty('file','Tidak ada sumber yang ditampilkan','Tambahkan bahan atau ubah pencarian judul sumber.');}
function renderTasks(){const a=S.data.analysis;const rows=a.tasks.filter(t=>S.taskFilter==='all'||(S.taskFilter==='done')===['done','selesai'].includes(t.status.toLowerCase()));
 shell(workspaceHeading()+`<section class="panel"><div class="section-heading"><div><h2>Pekerjaan yang perlu dilanjutkan</h2><p class="muted small-text">PIC, deadline, dan hambatan mengikuti sumber. Nilai yang kosong tidak ditebak.</p></div><select id="task-filter" aria-label="Filter pekerjaan"><option value="all" ${S.taskFilter==='all'?'selected':''}>Semua pekerjaan</option><option value="open" ${S.taskFilter==='open'?'selected':''}>Belum selesai</option><option value="done" ${S.taskFilter==='done'?'selected':''}>Selesai</option></select></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Pekerjaan</th><th>Status</th><th>PIC</th><th>Deadline</th><th>Hambatan & ketergantungan</th><th>Sumber</th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.title)}</strong></td><td><span class="task-status ${['done','selesai'].includes(t.status.toLowerCase())?'complete':''}">${esc({open:'Terbuka',in_progress:'Dikerjakan',done:'Selesai'}[t.status]||t.status)}</span></td><td>${esc(t.pic)||'<span class="missing-value">Belum tersedia</span>'}</td><td>${esc(t.deadline)||'<span class="missing-value">Belum tersedia</span>'}</td><td>${esc(t.blocker)||'—'}<small>${esc(t.dependency)}</small></td><td>${cite(t,'Buka sumber')}</td></tr>`).join('')}</tbody></table></div>`:empty('tasks','Belum ada pekerjaan pada tampilan ini','Tugas diekstrak dari CSV, JSON atau baris TASK yang terstruktur.')}</section>`);document.getElementById('task-filter').onchange=e=>{S.taskFilter=e.target.value;renderTasks();};
}
function renderGaps(){const a=S.data.analysis;shell(workspaceHeading()+`<div class="section-heading"><div><h2>Kejelasan sebelum serah terima</h2><p class="muted small-text">Temuan untuk ditinjau bersama, bukan penilaian kesiapan otomatis.</p></div><span class="badge amber">${a.missing.length+a.conflicts.length} temuan</span></div><div class="gap-list">${a.missing.map(g=>`<article class="gap-card"><span>${icon('alert')}</span><div><span class="mini-label">${g.field==='pic'?'PENANGGUNG JAWAB':'TENGGAT WAKTU'}</span><h3>${esc(g.task)}</h3><p>${g.field==='pic'?'PIC':'Deadline'} belum tercatat. Konfirmasikan sebelum tugas dilanjutkan.</p>${cite(g,'Periksa sumber')}</div></article>`).join('')}</div>${conflicts(a.conflicts)}${!a.missing.length&&!a.conflicts.length?empty('check','Tidak ada temuan terstruktur','Tetap tinjau sumber; pemeriksaan ini belum mencakup semua konteks pekerjaan.'):''}${a.warnings.length?`<div class="notice"><span>${icon('shield')}</span><div><strong>Instruksi dalam bahan tetap dianggap data.</strong><p>${a.warnings.length} baris berpola instruksi dikecualikan dari bukti. Deteksi ini terbatas, bukan jaminan keamanan menyeluruh.</p></div></div>`:''}`);}
function renderReview(){const w=S.data.workspace,b=S.data.briefs[0],giver=w.giver===S.user.id;
 shell(workspaceHeading()+pendingBrief()+clarificationsPanel()+`<section class="panel review-panel"><div class="review-intro"><span class="review-symbol">${icon('check')}</span><div><span class="eyebrow">HUMAN IN THE LOOP</span><h2>Serah terima perlu keputusan manusia.</h2><p class="muted">Tinjau versi, sumber, dan pekerjaan yang masih terbuka sebelum melanjutkan.</p></div></div><div class="handover-steps">${[['Draf','Draft'],['Ditinjau','Ready for Acceptance'],['Diterima','Accepted']].map(([n,k],i)=>`<div class="${w.status===k?'current':w.status==='Accepted'?'passed':''}"><span>${w.status==='Accepted'?icon('check'):i+1}</span><strong>${n}</strong></div>`).join('')}</div>${b?`<div class="review-version"><div><span class="mini-label">VERSI YANG DITINJAU</span><h3>${esc(b.id.slice(0,8))} <small>Revisi ${b.revision}</small></h3></div>${badge(b.status)}<a class="button secondary" href="${workspaceHref('workspace')}">Baca brief ${icon('arrow')}</a></div><div class="review-findings"><span>${icon('tasks')} ${b.tasks.filter(t=>!['done','selesai'].includes(t.status.toLowerCase())).length} tugas terbuka</span><span>${icon('alert')} ${b.missing.length} informasi kurang</span><span>${icon('file')} ${b.conflicts.length} konflik sumber</span></div><div class="brief-action-row">${reviewButtons(b,giver)}</div>`:empty('file',giver?'Belum ada versi untuk ditinjau':'Pemberi belum membagikan versi',giver?'Susun brief dari sumber penerima, lalu tinjau dan bagikan.':'Kamu akan dapat meninjau setelah pemberi membagikan versi.',giver?'<button class="button white" id="generate-review">Susun brief dengan agent '+icon('arrow')+'</button>':'')}</section>`);bindWorkspaceActions(b,giver);const cb=document.getElementById('connect-brief');if(cb)cb.onclick=()=>pairDialog('brief');}
function jobCard(j){return `<div class="pending-message"><div class="user-message"><span>Anda</span><p>${esc(j.question)}</p></div><div class="assistant-message"><div class="answer-byline"><img src="/logo.svg" alt=""><strong>Relayfy</strong><span class="badge neutral">${j.status==='Processing'?'Diproses tool':'Menunggu agent'}</span></div><div class="processing-panel"><div>${icon('check')} Identitas & izin diperiksa server</div><div>${icon('check')} Bukti berizin disiapkan</div><div><span class="spinner"></span> ${j.status==='Processing'?'Job telah diambil tool agent. Menunggu jawaban bersumber.':'Menunggu WorkBuddy mengambil job ini.'}</div></div><div class="pending-actions"><button class="text-btn" data-pair-ask>Hubungkan WorkBuddy ${icon('arrow')}</button><button class="text-btn muted" data-cancel-job="${j.id}">Batalkan</button></div></div></div>`;}
function renderAsk(){
 const activeJobs=S.jobs.filter(j=>j.mode==='ask'&&['Pending','Processing'].includes(j.status));
 const history=S.history.map(h=>`<article class="chat-turn"><div class="user-message"><span>Anda</span><p>${esc(h.question)}</p></div><div class="assistant-message"><div class="answer-byline"><img src="/logo.svg" alt=""><strong>Relayfy</strong><small>${h.result.origin==='retrieval'?'Bukti langsung':h.result.origin==='workbuddy_bridge'?'Melalui tool agent':'Model API'}</small></div><div class="answer-body">${answer(h.result)}</div><details class="source-trace"><summary>${icon('shield')} Sumber & proses yang tercatat</summary><p>Izin diperiksa sebelum pencarian. Jawaban mengikuti revisi ${h.result.access_revision}. ${h.result.origin==='retrieval'?'Tidak ada pemanggilan model.':'Kutipan diperiksa server; kesimpulan tetap perlu ditinjau.'}</p><div>${(h.result.evidence||[]).map(e=>cite(e)).join('')}</div></details><div class="answer-bottom">${icon('check')} ${h.result.unknown?'Bukti tidak tersedia; tidak ada informasi yang ditebak.':'Hasil tersimpan. Periksa kutipan sebelum dipakai.'}</div></div></article>`).join('');
 shell(`<div class="chat-frame"><div class="chat-header"><div><span class="eyebrow">ASK RELAYFY</span><h1>Chat</h1><p class="muted">${esc(S.data.workspace.name)}</p></div><button class="button secondary small" id="chat-sources">${icon('file')} ${S.data.sources.length} sumber berizin</button></div><div class="chat-feed" id="chat-feed">${history}${activeJobs.map(jobCard).join('')}${!history&&!activeJobs.length?`<div class="chat-empty"><span class="chat-empty-mark"><img src="/logo.svg" alt=""></span><span class="eyebrow">KONTEKS UNTUK LANGKAH BERIKUTNYA</span><h2>Apa yang ingin kamu lanjutkan?</h2><p>Tanyakan keputusan, pekerjaan terbuka,<br>atau informasi yang belum jelas pada handover ini.</p><div class="chat-suggestions">${['Mengapa peluncuran tertunda?','Kapan jadwal peluncuran?','Siapa PIC pembayaran?'].map(q=>`<button data-question="${q}"><span>${q}</span>${icon('arrow')}</button>`).join('')}</div><div class="chat-empty-foot">${icon('shield')} Hanya sumber yang boleh kamu baca yang dicari.</div></div>`:''}</div><div class="composer-wrap"><form id="ask-form" class="composer"><div class="composer-top"><span>${icon('box')} ${esc(S.data.workspace.name)}</span><select id="answer-mode" aria-label="Mode jawaban"><option value="agent" ${S.answerMode==='agent'?'selected':''}>${S.meta.backend==='workbuddy'?'WorkBuddy agent':'Model API'}</option><option value="evidence" ${S.answerMode==='evidence'?'selected':''}>Bukti sumber · tanpa AI</option></select></div><label class="sr-only" for="question">Pertanyaan</label><textarea id="question" rows="2" maxlength="2000" required placeholder="Tanyakan sesuatu tentang handover ini…">${esc(S.draft)}</textarea><div class="composer-bottom"><button class="icon-btn" id="composer-source" type="button" aria-label="Buka sumber">${icon('plus')}</button><span>${S.meta.backend==='workbuddy'?'Agent berjalan di WorkBuddy setelah tool terhubung.':'Jawaban menggunakan konfigurasi API backend.'}</span><button type="submit" class="send-button" aria-label="Kirim pertanyaan">${icon('up')}</button></div></form><div class="composer-note">${icon('shield')} Perubahan akses berlaku pada permintaan berikutnya, termasuk kutipan dan riwayat.</div></div></div>`);
 document.getElementById('chat-sources').onclick=()=>location.hash='sources/'+S.wid;document.getElementById('composer-source').onclick=()=>location.hash='sources/'+S.wid;
 document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{S.draft=b.dataset.question;document.getElementById('question').value=S.draft;document.getElementById('question').focus();});
 document.getElementById('answer-mode').onchange=e=>S.answerMode=e.target.value;
 const q=document.getElementById('question');q.oninput=()=>S.draft=q.value;q.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();document.getElementById('ask-form').requestSubmit();}};
 document.getElementById('ask-form').onsubmit=async e=>{e.preventDefault();const question=q.value.trim();if(!question)return;const btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{const mode=document.getElementById('answer-mode').value;await api('ask',{workspace:S.wid,question,answer_mode:mode==='evidence'?'evidence':'agent'});S.draft='';await reloadData();renderAsk();document.getElementById('chat-feed').scrollTop=999999;}catch(err){toast(err.message,true);btn.disabled=false;}};
 document.querySelectorAll('[data-pair-ask]').forEach(b=>b.onclick=()=>pairDialog('ask'));
}
function renderActivity(){
 const labels={create:'Workspace dibuat',ask:'Bukti dicari',brief_draft:'Draf dibuat',approved:'Tindakan disetujui',approval_requested:'Persetujuan diminta',ai_answer:'Jawaban disimpan',model_failed:'Model gagal',agent_requested:'Permintaan dikirim ke antrean agent',agent_claimed:'Tool agent mengambil job',agent_completed:'Keluaran tool diterima & divalidasi',agent_failed:'Agent melaporkan kegagalan',agent_cancelled:'Antrean dibatalkan',agent_paired:'Koneksi agent dibuat'};
 shell(heading('ACCOUNTABILITY, IN VIEW','Setiap langkah, tercatat.','Permintaan, sumber, hasil, dan persetujuan milik akunmu.',`<button class="button secondary" id="refresh-log">${icon('refresh')} Muat ulang</button>`)+`<div class="notice"><span>${icon('shield')}</span><p>Log hanya menampilkan aktivitasmu pada revisi aktif. Entri revisi lama disimpan privat dan disembunyikan setelah perubahan sumber atau izin.</p></div><section class="panel activity-panel"><div class="section-heading"><h2>Activity log</h2><span class="muted small-text">Revisi ${S.data.workspace.revision}</span></div>${S.audit?.length?`<div class="timeline">${S.audit.slice().reverse().map(r=>`<article class="event"><span class="event-icon ${r.action==='approved'?'success':''}">${icon(r.action==='approved'?'check':r.action.includes('failed')?'alert':r.action.includes('agent')?'link':'log')}</span><div><div class="event-heading"><h3>${esc(labels[r.action]||r.action)}</h3><time>${esc(fmt(r.at))}</time></div><details><summary>Detail aktivitas</summary><pre>${esc(JSON.stringify(JSON.parse(r.body),null,2))}</pre></details></div></article>`).join('')}</div>`:empty('log','Belum ada aktivitas pada revisi ini','Permintaan dan persetujuanmu akan ditampilkan di sini.')}</section>`);document.getElementById('refresh-log').onclick=()=>loadRoute();}
function renderConnection(){shell(heading('WORKBUDDY RUNTIME','Agent bekerja. Konteks terjaga.','Hubungkan tool WorkBuddy untuk memproses permintaan dari workspace ini.')+`<section class="panel connection-panel"><span class="connection-symbol">${icon('link')}</span><div><h2>${S.agent?.active?'Tool agent baru saja terhubung':'Hubungkan WorkBuddy lokal'}</h2><p>Web menyiapkan pekerjaan dan bukti sesuai izin. WorkBuddy mengambil job, menyusun jawaban, lalu mengembalikannya untuk divalidasi server.</p><div class="connection-status"><span class="${S.agent?.active?'green-dot':'grey-dot'}"></span>${S.agent?.last_seen?'Tool terakhir menghubungi server '+new Date(S.agent.last_seen*1000).toLocaleTimeString('id-ID'):'Belum ada tool yang terhubung pada profil dan revisi ini.'}</div><button class="button white" id="pair-start">Siapkan koneksi ${icon('arrow')}</button></div></section><div class="connection-how"><div><span>01</span><h3>Pilih satu konteks</h3><p>Koneksi terikat pada profil, workspace, revisi, dan tujuan. Gunakan task baru saat konteks berubah.</p></div><div><span>02</span><h3>Buka folder agent</h3><p>Gunakan folder <code>relayfy-agent</code> di WorkBuddy. Baca instruksi lokal dan hubungkan MCP atau jalankan client CLI.</p></div><div><span>03</span><h3>Jalankan tool nyata</h3><p>Ambil job, susun jawaban dari bukti, lalu kirim hasil. Status dan sumber tercatat pada activity log.</p></div></div><div class="notice"><span>${icon('shield')}</span><p>Tool ini tidak memiliki endpoint persetujuan atau pengubah izin. Semua keputusan review, berbagi, dan penerimaan tetap melalui UI pengguna.</p></div><p class="small-text muted">Status koneksi membuktikan tool menghubungi server. Bukti aplikasi WorkBuddy benar-benar dipakai tetap perlu direkam dari WorkBuddy.</p>`);document.getElementById('pair-start').onclick=()=>pairDialog();}
function guideContent(){return `${heading('START HERE','Satu handover, langkah yang jelas.','Panduan singkat untuk mencoba Relayfy secara lokal.')}<div class="guide-grid"><section class="panel"><h2>1. Pilih konteks</h2><p>Pada demo, gunakan Andi sebagai pemberi dan Maya sebagai penerima. Sari dan Dewi menunjukkan akses anggota yang berbeda. Semua profil dan bahan fiktif.</p><h2>2. Kenali sumber</h2><p>Buka workspace, periksa dokumen, chat, dan tugas yang boleh diakses. Tidak semua profil dapat melihat bahan yang sama.</p><h2>3. Tanya atau susun brief</h2><p>Mode WorkBuddy mengantrekan permintaan sampai tool agent berjalan. Mode “Bukti sumber” menampilkan kutipan langsung tanpa AI. Pemberi juga bisa menyusun ringkasan ekstraktif.</p></section><section class="panel"><h2>4. Hubungkan WorkBuddy</h2><p>Gunakan tombol Hubungkan WorkBuddy, unduh koneksi ke folder agent, dan buka task baru. Instruksi lengkap berada pada <code>relayfy-agent/START_HERE.md</code>.</p><h2>5. Tinjau & terima</h2><p>Andi meninjau dan membagikan versi. Maya meminta klarifikasi atau menerima versi setelah memeriksa sumber. Klik konfirmasi hanya setelah detailnya benar.</p><h2>6. Uji perubahan akses</h2><p>Andi dapat mengubah audiens sumber. Revisi baru membatalkan hasil dan koneksi agent lama. Tutup task WorkBuddy sebelumnya sebelum pairing ulang.</p></section></div><div class="notice"><span>${icon('alert')}</span><p>Ini MVP lokal. Belum ada klaim penggunaan WorkBuddy aktual, dataset resmi, atau angka penghematan. Jangan memasukkan data perusahaan nyata sebelum pengamanan dan evaluasi selesai.</p></div>`;}
function renderGuide(){if(S.user)shell(guideContent());else{app.innerHTML=publicNav()+`<main class="public-guide">${guideContent()}</main>`;bindTheme();}}
function bindContent(){
 document.querySelectorAll('[data-cite]').forEach(b=>b.onclick=async()=>{const epoch=S.epoch;try{const e=await api('cite',{workspace:S.wid,citation:b.dataset.cite},'GET');if(epoch!==S.epoch)return;showDialog(`<span class="eyebrow">SOURCE CHECK</span><h2>${esc(e.title||'Sumber')}</h2>${e.text?`<p class="muted small-text">${esc(e.citation)} · Versi ${e.version}${e.effective?' · Berlaku '+esc(e.effective):''}</p><blockquote class="source-quote">${esc(e.text)}</blockquote>`:`<p>${esc(e.message)}</p>`}`);}catch(e){toast(e.message,true);}});
 document.querySelectorAll('[data-source]').forEach(b=>b.onclick=async()=>{const epoch=S.epoch;try{const s=await api('source',{workspace:S.wid,id:b.dataset.source},'GET');if(epoch!==S.epoch)return;showDialog(`<span class="eyebrow">DOKUMEN SUMBER</span><h2>${esc(s.title)}</h2><p class="muted small-text">${esc(s.kind)} · Versi ${s.version}${s.effective?' · '+esc(s.effective):''}</p><pre class="source-body">${esc(s.body)}</pre>`,true);}catch(e){toast(e.message,true);}});
 document.querySelectorAll('[data-acl]').forEach(b=>b.onclick=()=>aclDialog(b.dataset.acl));
 document.querySelectorAll('[data-cancel-job]').forEach(b=>b.onclick=async()=>{try{await api('cancel_job',{workspace:S.wid,id:b.dataset.cancelJob});await loadRoute();toast('Antrean dibatalkan.');}catch(e){toast(e.message,true);}});
}
function createDialog(){showDialog(`<span class="eyebrow">HANDOVER BARU</span><h2>Beri pekerjaan konteks baru.</h2><p class="muted">Pilih nama proyek dan penerima yang sudah memiliki akun.</p><form id="create-form"><label>Nama workspace<input name="name" required maxlength="120" placeholder="Contoh: Handover website Karsa"></label><label>Email penerima<input name="receiver_email" type="email" required placeholder="nama@perusahaan.com" ${S.meta.demo?'list="demo-emails"':''}></label>${S.meta.demo?'<datalist id="demo-emails">'+S.profiles.filter(x=>x.id!==S.user.id).map(x=>`<option value="${esc(x.email)}">${esc(x.name)}</option>`).join('')+'</datalist>':''}<p class="form-error" id="dialog-error" role="alert"></p><button class="button white full">Buat workspace ${icon('arrow')}</button></form>`);document.getElementById('create-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const w=await api('create',Object.fromEntries(new FormData(e.target)));modal.close();location.hash='workspace/'+w.id;toast('Workspace berhasil dibuat.');}catch(err){document.getElementById('dialog-error').textContent=err.message;b.disabled=false;}};}
function sourceDialog(){showDialog(`<span class="eyebrow">BAHAN HANDOVER</span><h2>Tambahkan sumber.</h2><p class="muted">Sumber baru membuka revisi baru. Periksa isi dan audiens sebelum menyimpan.</p><form id="source-form"><label>Judul sumber<input name="title" required maxlength="200" placeholder="Catatan proyek, chat, atau tugas"></label><div class="form-row"><label for="source-kind">Jenis<select id="source-kind" name="kind" aria-label="Jenis sumber"><option value="document">Dokumen teks</option><option value="chat">Ekspor chat</option><option value="tasks">Daftar tugas</option></select></label><label>Tanggal informasi berlaku<input name="effective" type="date"></label></div><label class="file-input-label">${icon('plus')} Unggah TXT, MD, CSV, atau JSON<input id="source-file" type="file" accept=".txt,.md,.csv,.json"></label><label>Isi sumber<textarea name="body" required maxlength="100000" rows="7" placeholder="Tempel bahan. Format tugas: TASK|judul|status|pic|deadline|hambatan|ketergantungan"></textarea></label><fieldset><legend>Audiens sumber</legend>${S.data.members.map(m=>`<label class="check-label"><input type="checkbox" name="users" value="${m.id}" checked ${m.id===S.user.id?'disabled':''}>${esc(m.name)}${m.id===S.user.id?' (kamu)':''}</label>`).join('')}</fieldset><p class="form-error" id="dialog-error" role="alert"></p><button class="button white full">Tinjau sebelum menyimpan ${icon('arrow')}</button></form>`,true);
 document.getElementById('source-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('File maksimal 100 KB.');if(!/\.(txt|md|csv|json)$/i.test(f.name))throw Error('Pilih TXT, MD, CSV, atau JSON.');let text=await f.text();if(/\.(csv|json)$/i.test(f.name)){text=tasksText(text,f.name);document.getElementById('source-kind').value='tasks';}document.querySelector('#source-form [name=body]').value=text;const t=document.querySelector('#source-form [name=title]');if(!t.value)t.value=f.name;}catch(err){document.getElementById('dialog-error').textContent=err.message;}};
 document.getElementById('source-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);approval('import',{title:f.get('title'),kind:f.get('kind'),effective:f.get('effective'),body:f.get('body'),users:[...new Set([S.user.id,...f.getAll('users')])]},'Simpan & bagikan sumber','Pastikan isi dan audiens benar. Brief, riwayat, dan koneksi agent pada revisi sebelumnya akan tidak berlaku.');};
}
function tasksText(text,filename){let rows;if(/\.json$/i.test(filename)){rows=JSON.parse(text);if(!Array.isArray(rows))throw Error('JSON tugas harus berupa array objek.');}else{let records=[],record=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){record.push(cell);cell='';}else if(c==='\n'&&!quoted){record.push(cell.replace(/\r$/,''));records.push(record);record=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV memiliki tanda kutip tidak tertutup.');if(cell||record.length){record.push(cell.replace(/\r$/,''));records.push(record);}const keys=(records.shift()||[]).map(x=>x.trim().replace(/^\uFEFF/,''));rows=records.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(keys.map((k,i)=>[k,r[i]||''])));}
 return rows.map(r=>{if(!r||typeof r.title!=='string'||!r.title.trim())throw Error('Setiap tugas wajib memiliki title.');return 'TASK|'+['title','status','pic','deadline','blocker','dependency'].map(k=>String(r[k]||'').replace(/[|\r\n]/g,' ')).join('|');}).join('\n');}
function aclDialog(sid){const s=S.data.sources.find(x=>x.id===sid);showDialog(`<span class="eyebrow">KENDALI AKSES</span><h2>${esc(s.title)}</h2><p class="muted">Perubahan akses membatalkan hasil turunan dan koneksi agent sebelumnya. Data yang sudah dilihat tidak dapat ditarik kembali.</p><form id="acl-form"><fieldset><legend>Anggota yang boleh membaca</legend>${S.data.members.map(m=>`<label class="check-label"><input type="checkbox" name="users" value="${m.id}" ${s.users.includes(m.id)?'checked':''} ${m.id===S.user.id?'disabled':''}>${esc(m.name)}</label>`).join('')}</fieldset><button class="button white full">Tinjau perubahan akses ${icon('arrow')}</button></form>`);document.getElementById('acl-form').onsubmit=e=>{e.preventDefault();approval('acl',{source:sid,users:[...new Set([S.user.id,...new FormData(e.target).getAll('users')])]},'Ubah audiens sumber','Periksa audiens baru. Perubahan berlaku pada request berikutnya, termasuk kutipan, brief, riwayat dan koneksi agent.');};}
async function approval(action,payload,title,desc){try{const w=S.wid,plan=await api('plan',{workspace:w,action,payload});const summary={tindakan:action,revisi:plan.revision,...payload};if(payload.users)summary.users=payload.users.map(nameOf);showDialog(`<span class="eyebrow">PERSETUJUAN MANUSIA</span><h2>${esc(title)}</h2><p class="muted">${esc(desc)}</p><div class="approval-context">${icon('shield')} ${esc(S.user.name)} · ${esc(S.data.workspace.name)} · Revisi ${plan.revision}</div><details open><summary>Detail yang akan dijalankan</summary><pre>${esc(JSON.stringify(summary,null,2))}</pre></details><p class="tiny muted">Tidak ada tindakan dijalankan sampai kamu mengonfirmasi. Identitas, izin dan versi diperiksa kembali oleh server.</p><p class="form-error" id="dialog-error" role="alert"></p><div class="dialog-actions"><button class="button secondary" id="cancel-plan">Batal</button><button class="button white" id="confirm-plan">Konfirmasi & lanjutkan ${icon('check')}</button></div>`,action==='import');document.getElementById('cancel-plan').onclick=()=>modal.close();document.getElementById('confirm-plan').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await api('confirm',{workspace:w,plan:plan.plan,confirmed:true});modal.close();await loadRoute();toast('Tindakan berhasil disetujui.');}catch(err){document.getElementById('dialog-error').textContent=err.message;b.disabled=false;}};}catch(e){toast(e.message,true);}}
async function generate(op,button){button.disabled=true;button.textContent='Menyiapkan…';try{const r=await api(op,{workspace:S.wid});await loadRoute();if(r.queued){S.pairPurpose='brief';toast('Brief diantrekan. Jalankan agent WorkBuddy dengan tujuan brief.');}else toast(op==='extractive'?'Ringkasan bukti siap ditinjau. Ini bukan keluaran model AI.':'Draf siap ditinjau.');}catch(e){toast(e.message,true);button.disabled=false;button.textContent=op==='extractive'?'Lihat ringkasan bukti':'Susun brief dengan agent';}}
function pairDialog(purpose=S.pairPurpose||'ask'){
 if(S.meta.backend!=='workbuddy'){showDialog(`<h2>Konfigurasi model API</h2><p class="muted">Mode ini menggunakan API backend. Isi OPENAI_API_KEY dan OPENAI_MODEL melalui .env lokal, lalu restart. Jangan menempelkan secret ke chat.</p><p>Untuk demo WorkBuddy, jalankan <code>python run_demo.py</code>.</p>`);return;}
 const giver=S.data.workspace.giver===S.user.id;
 showDialog(`<span class="eyebrow">WORKBUDDY · LOCAL CONNECTION</span><h2>Satu profil. Satu konteks.</h2><p class="muted">Buka task WorkBuddy baru untuk ${esc(S.user.name)}, revisi ${S.data.workspace.revision}. Koneksi tidak dapat menyetujui tindakan atau mengubah izin.</p><form id="pair-form"><label for="pair-purpose">Tujuan koneksi<select id="pair-purpose" name="purpose"><option value="ask">Jawab pertanyaan akun ini</option>${giver?`<option value="brief" ${purpose==='brief'?'selected':''}>Susun brief untuk penerima</option>`:''}</select></label><div class="notice"><span>${icon('shield')}</span><p>Tutup task lama ketika berganti profil, revisi, atau tujuan. Jangan membawa konteks chat sebelumnya.</p></div><p class="form-error" id="dialog-error" role="alert"></p><button class="button white full">Siapkan file koneksi ${icon('arrow')}</button></form>`);
 document.getElementById('pair-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const purpose=new FormData(e.target).get('purpose');try{const config=await api('agent_pair',{workspace:S.wid,purpose});S.pairPurpose=purpose;showDialog(`<span class="eyebrow">KONEKSI SIAP DISIMPAN</span><h2>Teruskan ke WorkBuddy.</h2><p class="muted">Profil ${esc(S.user.name)} · Revisi ${config.revision} · ${purpose==='brief'?'Brief penerima':'Pertanyaan akun'}</p><ol class="connection-steps"><li>Unduh file koneksi. Simpan sebagai <code>relayfy-connection.json</code> di folder <code>relayfy-agent</code>.</li><li>Buka folder agent tersebut di WorkBuddy dan mulai <strong>task baru</strong>.</li><li>Tempel prompt dari <code>START_HERE.md</code>. Gunakan MCP tools atau client CLI yang disediakan.</li><li>Ajukan pertanyaan/brief dari web, lalu minta WorkBuddy memproses satu job.</li></ol><button class="button white full" id="download-connection">${icon('download')} Unduh relayfy-connection.json</button><p class="tiny muted">File ini berisi token terbatas. Jangan masukkan ke Git, screenshot, atau bagikan ke orang lain. Pairing baru mengganti koneksi sebelumnya untuk akun ini.</p>`);document.getElementById('download-connection').onclick=()=>{const blob=new Blob([JSON.stringify(config,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='relayfy-connection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Simpan file ke folder relayfy-agent di laptopmu.');};}catch(err){document.getElementById('dialog-error').textContent=err.message;b.disabled=false;}};
}
async function reloadData(){const wid=S.wid;const r=await Promise.all([api('workspace',{workspace:wid},'GET'),api('history',{workspace:wid},'GET'),api('jobs',{workspace:wid},'GET'),api('agent_status',{workspace:wid},'GET')]);if(wid!==S.wid)return;[S.data,S.history,S.jobs,S.agent]=r;if(S.route==='activity')S.audit=await api('audit',{workspace:wid},'GET');}
const views={dashboard:renderDashboard,workspace:renderWorkspace,sources:renderSources,tasks:renderTasks,gaps:renderGaps,review:renderReview,ask:renderAsk,activity:renderActivity,connection:renderConnection,guide:renderGuide};
async function loadRoute(){const epoch=++S.epoch;S.loading=true;S.mobile=false;const parts=location.hash.slice(1).split('/');S.route=parts[0]||'home';const requested=parts[1];try{
 if(S.route==='home'){renderHome();return;}
 if(S.route==='profiles'){await renderProfiles();return;}
 if(['login','register'].includes(S.route)){renderAuth(S.route==='register');return;}
 if(S.route==='guide'&&!S.user){renderGuide();return;}
 if(!S.user){location.hash=S.meta.demo?'profiles':'login';return;}
 if(!views[S.route]){location.hash='dashboard';return;}
 S.spaces=await api('workspaces');if(epoch!==S.epoch)return;
 S.wid=requested||S.spaces[0]?.id||'';S.data=null;S.history=[];S.jobs=[];S.agent=null;
 if(S.wid)await reloadData();if(epoch!==S.epoch)return;
 if(!S.data&&!['dashboard','guide'].includes(S.route)){shell(heading('WORKSPACE','Mulai dari sebuah handover.','Buat workspace di Ringkasan untuk mulai mengumpulkan konteks.')+empty('box','Belum ada workspace','Pilih penerima yang sudah terdaftar.','<a class="button white" href="#dashboard">Ke ringkasan '+icon('arrow')+'</a>'));return;}
 views[S.route]();
 }catch(err){if(epoch!==S.epoch)return;if(S.user){shell(heading('WORKSPACE','Konteks belum dapat dimuat.',esc(err.message))+`<button class="button secondary" id="retry">Coba lagi ${icon('refresh')}</button>`);document.getElementById('retry').onclick=loadRoute;}else{renderHome();toast(err.message,true);}}finally{if(epoch===S.epoch)S.loading=false;}}
let polling=false;async function poll(){if(polling||S.loading||!S.user||!S.data||document.hidden)return;polling=true;const who=S.user.id,wid=S.wid,epoch=S.epoch;try{const [spaces,jobs,status]=await Promise.all([api('workspaces'),api('jobs',{workspace:wid},'GET'),api('agent_status',{workspace:wid},'GET')]);if(who!==S.user?.id||epoch!==S.epoch||wid!==S.wid)return;const w=spaces.find(x=>x.id===wid);if(!w||w.revision!==S.data.workspace.revision){modal.close();S.draft='';await loadRoute();toast('Sumber atau akses berubah. Task dan koneksi agent lama tidak berlaku.');return;}const changed=JSON.stringify(jobs)!==JSON.stringify(S.jobs)||w.status!==S.data.workspace.status;S.spaces=spaces;S.agent=status;const badge=document.getElementById('agent-connect');if(badge&&S.meta.backend==='workbuddy'){badge.classList.toggle('online',status.active);badge.querySelector('span').textContent=status.active?'Tool agent aktif':'WorkBuddy belum aktif';}if(changed&&!modal.open){const draft=document.getElementById('question');const focused=draft===document.activeElement;if(draft)S.draft=draft.value;await reloadData();views[S.route]();if(focused&&S.route==='ask')document.getElementById('question').focus();}}catch(e){if(S.user)console.debug('Konteks akan diperiksa ulang pada permintaan berikutnya.');}finally{polling=false;}}
async function boot(){app.innerHTML='<div class="boot-state"><img src="/logo.svg" alt=""><span>Menyiapkan konteks…</span></div>';try{S.meta=await api('meta');if(S.meta.demo)S.profiles=await api('profiles');try{const r=await api('session');S.user=r.user;S.csrf=r.csrf;}catch{}await loadRoute();}catch(e){app.innerHTML=`<main class="boot-error"><h1>Relayfy belum dapat dijangkau.</h1><p>${esc(e.message)}</p><button class="button white" id="boot-retry">Coba lagi</button></main>`;document.getElementById('boot-retry').onclick=boot;}}
window.addEventListener('hashchange',()=>{modal.close();S.filter='';S.taskFilter='all';window.scrollTo(0,0);loadRoute();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});setInterval(poll,3000);boot();
